            }
            if (locSampler2 >= 0) {
                GL20.glUniform1i((int)locSampler2, (int)2);
            }
            GL20.glUseProgram((int)0);
            program = prog;
            return true;
        }
        catch (Throwable t) {
            YSMGeoCompat.LOGGER.error("YSM-GEO Compat: failed to compile the GPU skinning shader, falling back to the Epic Fight compute path", t);
            failed = true;
            return false;
        }

