@Mixin(targets={"com.elfmcys.yesstevemodel.geckolib3.core.controller.AnimationControllerRuntime"}, remap=false)
public abstract class YsmAnimationTransitionGuardMixin {
    private static volatile boolean NULL_TRANSITION_LOGGED = false;
    private static volatile boolean INVOKE_FAILED_LOGGED = false;
    private static final Map<Class<?>, Method> EVAL_METHODS = new ConcurrentHashMap();

    @Redirect(method={"evaluateTransitions(Lcom/elfmcys/yesstevemodel/molang/runtime/ExpressionEvaluator;)Z"}, at=@At(value="INVOKE", target="Lcom/elfmcys/yesstevemodel/geckolib3/core/molang/value/IValue;evalAsBoolean(Lcom/elfmcys/yesstevemodel/molang/runtime/ExpressionEvaluator;)Z"), require=0)
    private boolean ysmgeo$guardNullTransitionCondition(@Coerce Object condition, @Coerce Object evaluator) {
        if (condition == null) {
            if (!NULL_TRANSITION_LOGGED) {
                NULL_TRANSITION_LOGGED = true;
                YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: YSM animation transition has a null condition; treating it as false (the render-thread crash would otherwise happen inside YSM). This usually means the current model has a malformed animation transition.");
            }
            return false;
        }
        return YsmAnimationTransitionGuardMixin.invokeEvalAsBoolean(condition, evaluator);
    }

    private static boolean invokeEvalAsBoolean(Object condition, Object evaluator) {
        Method method = EVAL_METHODS.get(condition.getClass());
        if (method == null) {
            Method found = null;
            for (Method candidate : condition.getClass().getMethods()) {
                if (!"evalAsBoolean".equals(candidate.getName()) || candidate.getParameterCount() != 1 || candidate.getReturnType() != Boolean.TYPE) continue;
                found = candidate;
                break;
            }
            if (found == null) {
                if (!INVOKE_FAILED_LOGGED) {
                    INVOKE_FAILED_LOGGED = true;
                    YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: cannot find IValue#evalAsBoolean on {}; treating transitions as false", (Object)condition.getClass().getName());
                }
                return false;
            }
            Method previous = EVAL_METHODS.putIfAbsent(condition.getClass(), found);
            method = previous != null ? previous : found;
        }
        try {
            Boolean b;
            Object result = method.invoke(condition, evaluator);
            return result instanceof Boolean && (b = (Boolean)result) != false;
        }
        catch (Throwable t) {
            if (!INVOKE_FAILED_LOGGED) {
                INVOKE_FAILED_LOGGED = true;
                YSMGeoCompat.LOGGER.warn("YSM-GEO Compat: YSM transition condition evaluation failed, treating it as false", t);
            }
            return false;
        }
    }
}

