import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.AtomicMoveNotSupportedException;
import java.nio.file.Files;
import java.nio.file.OpenOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.attribute.FileAttribute;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.joml.Matrix4f;
import org.joml.Matrix4fc;
import org.joml.Vector3f;
import org.joml.Vector3fc;

public class EFMeshJsonWriter {
    private static final String[] HUMANOID_PARTS = new String[]{"head", "torso", "leftArm", "rightArm", "leftLeg", "rightLeg", "hat", "jacket", "leftSleeve", "rightSleeve", "leftPants", "rightPants"};
    public static final String BONE_PART_PREFIX = "y/";

    private static VertexKey keyOf(Vector3f pos, Vector3f normal, float u, float v, int jointId) {
        return new VertexKey(Math.round(pos.x() * 1000.0f), Math.round(pos.y() * 1000.0f), Math.round(pos.z() * 1000.0f), Math.round(normal.x() * 100.0f), Math.round(normal.y() * 100.0f), Math.round(normal.z() * 100.0f), Math.round(u * 4096.0f), Math.round(v * 4096.0f), jointId);
    }

    public static int writeTlmMesh(YSMGeoModel geoModel, float scale, Path outFile, String textureRL) throws IOException {
        if (geoModel == null) {
            return -1;
        }
        return EFMeshJsonWriter.writeMeshJson(geoModel, scale, scale, outFile, textureRL);
    }

    private static int writeMeshJson(YSMGeoModel geoModel, float scaleW, float scaleH, Path outFile, String textureRL) throws IOException {
        ArrayList<Float> positions = new ArrayList<Float>();
        ArrayList<Float> normals = new ArrayList<Float>();
        ArrayList<Float> uvs = new ArrayList<Float>();
        ArrayList<Integer> vcounts = new ArrayList<Integer>();
        ArrayList<Integer> vindices = new ArrayList<Integer>();
        HashMap<VertexKey, Integer> dedup = new HashMap<VertexKey, Integer>();
        LinkedHashMap<String, List<Integer>> partIndices = new LinkedHashMap<String, List<Integer>>();
        int[] quadCount = new int[]{0};
        for (YSMGeoModel.Bone rootBone : geoModel.topLevelBones) {
            EFMeshJsonWriter.walkBone(rootBone, new Matrix4f(), scaleW, scaleH, dedup, positions, normals, uvs, vcounts, vindices, partIndices, quadCount, 0);
        }
        if (positions.isEmpty()) {
            return -1;
        }
        JsonObject root = new JsonObject();
        JsonObject renderProperties = new JsonObject();
        renderProperties.addProperty("texture_path", textureRL);
        renderProperties.addProperty("transparent", Boolean.valueOf(false));
        root.add("render_properties", (JsonElement)renderProperties);
        JsonObject vertices = new JsonObject();
        vertices.add("positions", (JsonElement)EFMeshJsonWriter.floatArray(positions, 3));
        vertices.add("normals", (JsonElement)EFMeshJsonWriter.floatArray(normals, 3));
        vertices.add("uvs", (JsonElement)EFMeshJsonWriter.floatArray(uvs, 2));
        vertices.add("vcounts", (JsonElement)EFMeshJsonWriter.intArray(vcounts, 1));
        vertices.add("vindices", (JsonElement)EFMeshJsonWriter.intArray(vindices, 2));
        JsonObject weightsObj = new JsonObject();
        weightsObj.addProperty("stride", (Number)1);
        weightsObj.addProperty("count", (Number)1);
